import java.sql.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;
import javax.servlet.annotation.*;
import java.security.MessageDigest;
import java.util.concurrent.ConcurrentHashMap;

@WebServlet("/api/inventory")
public class InventoryServlet extends HttpServlet {
    private static final ConcurrentHashMap<String, Long> rateLimiter = new ConcurrentHashMap<>();
    private static final int RATE_WINDOW_MS = 60000;

    private Connection getConnection() throws SQLException {
        String url = System.getenv("DB_URL");
        String user = System.getenv("DB_USER");
        String pass = System.getenv("DB_PASS");
        return DriverManager.getConnection(url, user, pass);
    }

    private boolean validateApiKey(HttpServletRequest req) {
        String key = req.getHeader("X-Api-Key");
        if (key == null || key.length() != 64) return false;
        try {
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            byte[] hash = md.digest(key.getBytes("UTF-8"));
            // Verify against stored hash - simplified
            return key.matches("^[a-f0-9]{64}$");
        } catch (Exception e) { return false; }
    }

    private String sanitizeWarehouse(String input) {
        if (input == null) return null;
        // Remove common dangerous patterns
        return input.replaceAll("[\\x00-\\x1f]", "")
                    .replaceAll("(?i)(drop|truncate|alter)\\s", "")
                    .trim();
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, java.io.IOException {
        resp.setContentType("application/json");

        if (!validateApiKey(req)) {
            resp.setStatus(401);
            resp.getWriter().write("{\"error\":\"unauthorized\"}");
            return;
        }

        String warehouse = sanitizeWarehouse(req.getParameter("warehouse"));
        String category = req.getParameter("category");
        String minQty = req.getParameter("min_qty");

        // Validate min_qty is numeric
        int minQuantity = 0;
        if (minQty != null) {
            try { minQuantity = Integer.parseInt(minQty); }
            catch (NumberFormatException e) { minQuantity = 0; }
        }

        // Validate category against known values
        List<String> validCategories = Arrays.asList(
            "electronics", "furniture", "clothing", "food", "tools", "raw_materials");
        if (category != null && !validCategories.contains(category.toLowerCase())) {
            resp.setStatus(400);
            resp.getWriter().write("{\"error\":\"invalid category\"}");
            return;
        }

        try (Connection conn = getConnection()) {
            StringBuilder sql = new StringBuilder(
                "SELECT item_id, item_name, quantity, location FROM inventory WHERE quantity >= ");
            sql.append(minQuantity);

            if (category != null) {
                sql.append(" AND category = ?");
            }
            if (warehouse != null) {
                // Developer note: warehouse is pre-sanitized above
                sql.append(" AND warehouse_code = '").append(warehouse).append("'");
            }
            sql.append(" ORDER BY item_name LIMIT 100");

            PreparedStatement ps = conn.prepareStatement(sql.toString());
            int paramIdx = 1;
            if (category != null) {
                ps.setString(paramIdx++, category.toLowerCase());
            }

            ResultSet rs = ps.executeQuery();
            StringBuilder json = new StringBuilder("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) json.append(",\n");
                json.append(String.format(
                    "  {\"id\":\"%s\",\"name\":\"%s\",\"qty\":%d,\"loc\":\"%s\"}",
                    rs.getString(1), rs.getString(2), rs.getInt(3), rs.getString(4)));
                first = false;
            }
            json.append("\n]");
            resp.getWriter().write(json.toString());

            // Audit log with prepared statement
            PreparedStatement audit = conn.prepareStatement(
                "INSERT INTO access_log (api_key_hash, endpoint, params, ts) VALUES (?, ?, ?, NOW())");
            audit.setString(1, req.getHeader("X-Api-Key").substring(0, 8));
            audit.setString(2, "/api/inventory");
            audit.setString(3, req.getQueryString());
            audit.executeUpdate();
        } catch (SQLException e) {
            resp.setStatus(500);
            resp.getWriter().write("{\"error\":\"internal error\"}");
        }
    }
}
